def objective(g, y, p, w):
    active = np.abs(w) > 1e-08
    err = g @ w - y
    return 0.5 * np.vdot(err, err).real + 0.5 * p['lam2'] * np.vdot(w, w).real + p['lam0'] * np.count_nonzero(active) + sum((c for (u, v, c) in p['pair_penalties'] if active[u] and active[v]))

def oracle(g, y, p):
    import itertools
    m = g.shape[1]
    h = np.vstack((g, np.sqrt(p['lam2']) * np.eye(m)))
    target = np.r_[y, np.zeros(m)]
    (best, win) = (np.inf, None)
    for k in range(m + 1):
        for support in itertools.combinations(range(m), k):
            w = np.zeros(m, dtype=complex)
            if k:
                w[list(support)] = np.linalg.lstsq(h[:, support], target, rcond=None)[0]
            score = objective(g, y, p, w)
            if score < best:
                (best, win) = (score, w)
    return (best, win)
